CREATE COLUMN TABLE "TEST_AP"."APZ_TRANSFERLOG" ("ID" INTEGER CS_INT GENERATED BY DEFAULT AS IDENTITY, "DocEntry" INTEGER CS_INT, "TempKey" NVARCHAR(50), "BoxCode" NVARCHAR(50), "DocTransfer" INTEGER CS_INT, "Quantity" DECIMAL(19,6) CS_FIXED, "CreateTime" LONGDATE CS_LONGDATE DEFAULT CURRENT_DATE, PRIMARY KEY ("ID")) UNLOAD PRIORITY 5  AUTO MERGE 